#!/bin/sh
set -eu

role="${1:-master}"
script_dir="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
project_root="$(CDPATH= cd -- "${script_dir}/../.." && pwd)"
deploy_dir="${project_root}/deploy"
env_file="${deploy_dir}/.env"

case "${role}" in
  master) compose_file="${deploy_dir}/docker-compose-master.yml" ;;
  slave) compose_file="${deploy_dir}/docker-compose-slave.yml" ;;
  *) echo "Unknown role: ${role}" >&2; exit 2 ;;
esac

test -f "${env_file}" || { echo "Missing ${env_file}" >&2; exit 1; }

set -a
# deploy/.env is generated by this repository and contains shell-safe values.
. "${env_file}"
for private_env_file in "${deploy_dir}/.env.feishu" "${deploy_dir}/.env.secrets"; do
  if [ -f "${private_env_file}" ]; then
    . "${private_env_file}"
  fi
done
set +a

run_docker() {
  if docker info >/dev/null 2>&1; then
    docker "$@"
  elif sudo -n docker info >/dev/null 2>&1; then
    sudo -n env \
      "NODE_PUBLIC_IP=${NODE_PUBLIC_IP:-}" \
      "WAO_IMAGE_TAG=${WAO_IMAGE_TAG:-}" \
      docker "$@"
  else
    echo 'Docker is unavailable to the current user and passwordless sudo is not configured.' >&2
    return 1
  fi
}

run_compose() {
  if [ -n "${compose_profile:-}" ]; then
    run_docker compose --profile "${compose_profile}" "$@"
  else
    run_docker compose "$@"
  fi
}

compose() {
  legacy_env_file="${deploy_dir}/.env.feishu"
  secrets_env_file="${deploy_dir}/.env.secrets"
  if [ -f "${legacy_env_file}" ] && [ -f "${secrets_env_file}" ]; then
    run_compose --env-file "${env_file}" --env-file "${legacy_env_file}" --env-file "${secrets_env_file}" -f "${compose_file}" "$@"
  elif [ -f "${secrets_env_file}" ]; then
    run_compose --env-file "${env_file}" --env-file "${secrets_env_file}" -f "${compose_file}" "$@"
  elif [ -f "${legacy_env_file}" ]; then
    run_compose --env-file "${env_file}" --env-file "${legacy_env_file}" -f "${compose_file}" "$@"
  else
    run_compose --env-file "${env_file}" -f "${compose_file}" "$@"
  fi
}

print_deployment_diagnostics() {
  echo 'Deployment health check failed; collecting the failed containers before rollback.' >&2
  compose ps -a >&2 || true
  diagnostic_services="wao-server wao-agent-server wao-gateway"
  if [ "${role}" = "master" ]; then
    diagnostic_services="codex-egress-proxy ${diagnostic_services}"
  fi
  for service in ${diagnostic_services}; do
    container_id="$(compose ps -aq "${service}" 2>/dev/null || true)"
    if [ -z "${container_id}" ]; then
      echo "No container was created for ${service}." >&2
      continue
    fi
    echo "===== ${service} container state =====" >&2
    run_docker inspect --format \
      'status={{.State.Status}} exit_code={{.State.ExitCode}} oom_killed={{.State.OOMKilled}} error={{.State.Error}} health={{if .State.Health}}{{.State.Health.Status}}{{else}}none{{end}}' \
      "${container_id}" >&2 || true
    run_docker inspect --format '{{if .State.Health}}{{range .State.Health.Log}}{{.End}} exit={{.ExitCode}} {{printf "%s" .Output}}{{println}}{{end}}{{end}}' \
      "${container_id}" >&2 || true
    echo "===== ${service} recent logs =====" >&2
    compose logs --no-color --timestamps --tail 200 "${service}" >&2 || true
  done
}

if [ "${role}" = "master" ]; then
  case "${MANAGE_MASTER_INFRA:-true}" in
    true) compose_profile=managed-infra ;;
    false)
      : "${MYSQL_HOST:?MYSQL_HOST is required when MANAGE_MASTER_INFRA=false}"
      : "${NACOS_SERVER_ADDR:?NACOS_SERVER_ADDR is required when MANAGE_MASTER_INFRA=false}"
      ;;
    *) echo 'MANAGE_MASTER_INFRA must be true or false.' >&2; exit 2 ;;
  esac
fi

if [ "${GATEWAY_SSL_ENABLED:-true}" = "true" ]; then
  gateway_keystore="${deploy_dir}/certs/gateway.p12"
  test -f "${gateway_keystore}" || { echo "Missing ${gateway_keystore}" >&2; exit 1; }
  # The container runs as a non-root user. PKCS#12 contents remain protected by
  # GATEWAY_SSL_PASS while the bind-mounted file must be readable in-container.
  chmod 0644 "${gateway_keystore}"
fi

detect_public_ipv4() {
  case "${role}" in
    master) host="${MASTER_PUBLIC_HOST:-linux2.wayuwa.cn}" ;;
    slave) host="${SLAVE_PUBLIC_HOST:-windows1.wayuwa.cn}" ;;
  esac
  getent ahostsv4 "${host}" 2>/dev/null | awk '$2 == "STREAM" { print $1; exit }'
}

NODE_PUBLIC_IP="${NODE_PUBLIC_IP:-$(detect_public_ipv4)}"
if [ -z "${NODE_PUBLIC_IP}" ] && [ -f "${deploy_dir}/.public-ip" ]; then
  NODE_PUBLIC_IP="$(sed -n '1p' "${deploy_dir}/.public-ip" | tr -d '\r\n')"
fi
if [ -z "${NODE_PUBLIC_IP}" ]; then
  NODE_PUBLIC_IP="$(curl -4fsS --max-time 10 https://api.ipify.org || curl -4fsS --max-time 10 https://4.ipw.cn)"
fi
case "${NODE_PUBLIC_IP}" in
  *[!0-9.]*|'') echo "Invalid public IPv4 address: ${NODE_PUBLIC_IP}" >&2; exit 1 ;;
esac
export NODE_PUBLIC_IP

compose config >/dev/null

legacy_agent_project="wao-agent-${role}"
legacy_agent_id="$(run_docker ps -aq \
  --filter "label=com.docker.compose.project=${legacy_agent_project}" \
  --filter 'label=com.docker.compose.service=wao-agent-server' | head -n 1)"
if [ -n "${legacy_agent_id}" ]; then
  legacy_agent_image="$(run_docker inspect --format '{{.Image}}' "${legacy_agent_id}")"
  run_docker tag "${legacy_agent_image}" wao-agent-server:rollback
fi

for service in wao-server wao-agent-server wao-gateway; do
  container_id="$(compose ps -q "${service}")"
  if [ -n "${container_id}" ]; then
    image_id="$(run_docker inspect --format '{{.Image}}' "${container_id}")"
    run_docker tag "${image_id}" "${service}:rollback"
  fi
done
case "${SKIP_IMAGE_BUILD:-false}" in
  true)
    required_images="wao-server:${WAO_IMAGE_TAG:-latest} wao-agent-server:${WAO_IMAGE_TAG:-latest} wao-gateway:${WAO_IMAGE_TAG:-latest}"
    if [ "${role}" = "master" ]; then
      required_images="wao-codex-egress-proxy:${WAO_IMAGE_TAG:-latest} ${required_images}"
    fi
    # Deliberately split the trusted, internally constructed image list.
    # shellcheck disable=SC2086
    run_docker image inspect ${required_images} >/dev/null
    ;;
  false)
    if [ "${role}" = "master" ]; then
      compose build codex-egress-proxy wao-server wao-agent-server wao-gateway
    else
      compose build wao-server wao-agent-server wao-gateway
    fi
    ;;
  *) echo 'SKIP_IMAGE_BUILD must be true or false.' >&2; exit 2 ;;
esac

start_services() {
  # 首次统一发布时，精确接管旧 Compose 项目的 Agent 容器。镜像已在上面标记为 rollback，
  # 媒体卷也通过显式 name 继续挂载，失败时仍可用统一 Compose 恢复。
  if [ -n "${legacy_agent_id}" ]; then
    run_docker rm -f "${legacy_agent_id}" >/dev/null || return 1
  fi
  if [ "${role}" = "master" ]; then
    # The proxy tag is reused between releases. Force recreation so Docker does
    # not keep a healthy container that still points at the previous image ID.
    compose up -d --force-recreate --wait codex-egress-proxy || return 1
  fi
  compose up -d --wait
}

if ! start_services; then
  print_deployment_diagnostics
  if run_docker image inspect wao-server:rollback wao-agent-server:rollback wao-gateway:rollback >/dev/null 2>&1; then
    echo 'Deployment failed; restoring the previously running application images.' >&2
    WAO_IMAGE_TAG=rollback compose up -d --no-build --no-deps --wait wao-server wao-agent-server wao-gateway
  fi
  exit 1
fi
compose ps

printf '%s\n' "${NODE_PUBLIC_IP}" >"${deploy_dir}/.public-ip"

if [ "${role}" = "master" ] && command -v crontab >/dev/null 2>&1; then
  cron_marker='# WAO public IP refresh'
  existing_crontab="$(crontab -l 2>/dev/null || true)"
  {
    printf '%s\n' "${existing_crontab}" | grep -vF "${cron_marker}" || true
    printf '%s\n' "*/5 * * * * cd '${project_root}' && sh deploy/scripts/refresh-public-ip.sh master ${cron_marker}"
  } | crontab -
fi
